/**
 * Search strategy.
 *
 * ``default`` (recommended) combines lexical and semantic search and is the
 * right choice for most use cases. ``keyword`` runs lexical search only — use
 * it for real-time, low-latency needs such as ad targeting. ``agentic`` uses
 * an LLM to plan multiple structured sub-searches for complex queries, with
 * higher latency than the other modes.
 */
export declare const SearchMode: {
    readonly Keyword: "keyword";
    readonly Default: "default";
    readonly Agentic: "agentic";
};
export type SearchMode = (typeof SearchMode)[keyof typeof SearchMode];
